import {Vec3} from 'playcanvas';
import type {CircuitPoint} from './closed-circuit';
import type {LandSample} from './land-track';
const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, x));
const vector = (p: CircuitPoint) => Array.isArray(p) ? new Vec3(...p as [number, number, number]) : new Vec3((p as Vec3).x, (p as Vec3).y, (p as Vec3).z);
/** Original open Hermite road with physical arc-length lookup. Endpoint direction
 * is explicit so independently authored fork ribbons share exact support frames. */
export class OpenRoad {
  readonly length: number;
  readonly points: readonly Vec3[];
  private readonly tangents: readonly Vec3[];
  private readonly arcs: readonly number[];
  private readonly steps: number;
  constructor(points: readonly CircuitPoint[], startDirection: CircuitPoint, endDirection: CircuitPoint) {
    if (points.length < 2) throw new Error('Open road needs two points');
    this.points = points.map(vector);
    if (this.points.some(p => ![p.x,p.y,p.z].every(Number.isFinite))) throw new Error('Nonfinite road knot');
    this.tangents = this.points.map((p,i) => i === 0 ? vector(startDirection).normalize() : i === points.length-1 ? vector(endDirection).normalize() : this.points[i+1].clone().sub(this.points[i-1]).normalize());
    this.steps = (points.length-1)*160;
    const arcs = [0]; let previous = this.point(0);
    for (let i=1;i<=this.steps;i++) { const p=this.point(i/this.steps); arcs.push(arcs[i-1]+p.clone().sub(previous).length()); previous=p; }
    this.arcs=arcs; this.length=arcs.at(-1)!;
    if (this.length < 1) throw new Error('Degenerate road');
  }
  private evaluate(u: number, derivative = false): Vec3 {
    const q=clamp(u,0,1)*(this.points.length-1), i=Math.min(this.points.length-2,Math.floor(q)), t=q-i;
    const a=this.points[i], b=this.points[i+1], len=b.clone().sub(a).length();
    const m=this.tangents[i], n=this.tangents[i+1];
    const h=derivative ? [6*t*t-6*t,3*t*t-4*t+1,-6*t*t+6*t,3*t*t-2*t] : [2*t*t*t-3*t*t+1,t*t*t-2*t*t+t,-2*t*t*t+3*t*t,t*t*t-t*t];
    return a.clone().mulScalar(h[0]).add(m.clone().mulScalar(h[1]*len)).add(b.clone().mulScalar(h[2])).add(n.clone().mulScalar(h[3]*len));
  }
  point(u: number) { return this.evaluate(u); }
  private parameter(s: number): number {
    const target=clamp(Number.isFinite(s)?s:0,0,this.length); let lo=0, hi=this.steps;
    while(lo+1<hi) { const m=(lo+hi)>>1; if(this.arcs[m]<=target)lo=m;else hi=m; }
    return (lo+(target-this.arcs[lo])/(this.arcs[hi]-this.arcs[lo]))/this.steps;
  }
  sample(s: number, lateral=0): LandSample {
    const u=this.parameter(s), p=this.point(u), t=this.evaluate(u,true).normalize(), n=new Vec3(t.z,0,-t.x).normalize(), normal=new Vec3().cross(t,n).normalize();
    p.add(n.clone().mulScalar(Number.isFinite(lateral)?lateral:0));
    return {p,t,n,normal,u:s/this.length,angle:Math.atan2(t.x,t.z),bank:0,grade:t.y/Math.max(1e-6,Math.hypot(t.x,t.z))};
  }
  curvature(s: number, span=7) { const a=this.sample(clamp(s,0,this.length)).t,b=this.sample(clamp(s+span,0,this.length)).t; return Math.atan2(a.z*b.x-a.x*b.z,a.x*b.x+a.z*b.z)/span; }
}

src/closed-circuit.ts.content:
import { Vec3 } from 'playcanvas';

export type CircuitPoint = Readonly<{x: number; y: number; z: number}> | readonly [number, number, number];
export type CircuitOptions = {arcSteps?: number; legacySeamTangent?: boolean};
type CubicAxis = readonly [number, number, number, number];
type CubicSegment = {x: CubicAxis; y: CubicAxis; z: CubicAxis};

/** Map-neutral, closed centripetal Catmull–Rom curve with a metre-distance table.
 * Geometry is built once; every scene, racer and camera consumes this sampler.
 * The legacy seam option exists solely to verify the historical migration route. */
export class ClosedCircuit {
  readonly points: readonly Vec3[];
  readonly arcs: number[] = [0];
  readonly length: number;
  readonly arcSteps: number;
  private readonly legacySeamTangent: boolean;
  private readonly segments: readonly CubicSegment[];
  constructor(points: readonly CircuitPoint[], options: CircuitOptions = {}) {
    if (points.length < 4) throw new Error('A closed circuit needs at least four points');
    this.points = points.map(point => Array.isArray(point) ? new Vec3(point[0], point[1], point[2]) : new Vec3((point as Vec3).x, (point as Vec3).y, (point as Vec3).z));
    if (this.points.some(point => ![point.x, point.y, point.z].every(Number.isFinite))) throw new Error('Circuit points must be finite');
    // Coefficients are static. Avoid rebuilding tangent weights and temporary
    // vectors for every rider/camera/wake sample on mobile devices.
    this.segments = this.points.map((_, segment) => {
      const n = this.points.length, [p0, p1, p2, p3] = [-1, 0, 1, 2].map(i => this.points[(segment + i + n) % n]);
      let d0 = Math.sqrt(p0.clone().sub(p1).length()), d1 = Math.sqrt(p1.clone().sub(p2).length()), d2 = Math.sqrt(p2.clone().sub(p3).length());
      if (d1 < 1e-4) d1 = 1;
      if (d0 < 1e-4) d0 = d1;
      if (d2 < 1e-4) d2 = d1;
      const axis = (a: number, b: number, c: number, d: number): CubicAxis => {
        const m1 = ((b - a) / d0 - (c - a) / (d0 + d1) + (c - b) / d1) * d1;
        const m2 = ((c - b) / d1 - (d - b) / (d1 + d2) + (d - c) / d2) * d1;
        return [b, m1, -3 * b + 3 * c - 2 * m1 - m2, 2 * b - 2 * c + m1 + m2];
      };
      return {x: axis(p0.x, p1.x, p2.x, p3.x), y: axis(p0.y, p1.y, p2.y, p3.y), z: axis(p0.z, p1.z, p2.z, p3.z)};
    });
    // Include every control knot in the distance table. Centripetal segments
    // share tangent directions but not parameter speed; straddling a knot in a
    // table interval would otherwise create a small visible speed pulse.
    this.arcSteps = Number.isFinite(options.arcSteps) ? Math.max(64, Math.floor(options.arcSteps!)) : Math.ceil(1800 / points.length) * points.length;
    this.legacySeamTangent = options.legacySeamTangent === true;
    let previous = this.point(0), total = 0;
    for (let i = 1; i <= this.arcSteps; i++) {
      const next = this.point(i / this.arcSteps);
      total += next.clone().sub(previous).length(); this.arcs.push(total); previous = next;
    }
    if (total < 1e-6) throw new Error('Circuit length must be positive');
    this.length = total;
  }
  point(parameter: number): Vec3 {
    const n = this.points.length;
    const p = (((Number.isFinite(parameter) ? parameter : 0) % 1) + 1) % 1 * n;
    const index = Math.floor(p), t = p - index, segment = this.segments[index];
    const component = ([a, b, c, d]: CubicAxis) => a + b * t + c * t * t + d * t * t * t;
    return new Vec3(component(segment.x), component(segment.y), component(segment.z));
  }
  parameterAt(u: number): number {
    const target = Math.max(0, Math.min(1, Number.isFinite(u) ? u : 0)) * this.length;
    let low = 0, high = this.arcs.length - 1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (this.arcs[mid] < target) low = mid + 1;
      else if (this.arcs[mid] > target) high = mid - 1;
      else return mid / this.arcSteps;
    }
    const index = Math.max(0, Math.min(this.arcSteps - 1, high));
    const span = this.arcs[index + 1] - this.arcs[index];
    return (index + (span > 0 ? (target - this.arcs[index]) / span : 0)) / this.arcSteps;
  }
  sample(distance: number, lateral = 0) {
    const u = (((Number.isFinite(distance) ? distance : 0) / this.length) % 1 + 1) % 1;
    const parameter = this.parameterAt(u), p = this.point(parameter);
    const before = this.legacySeamTangent ? Math.max(0, parameter - .0001) : parameter - .0001;
    const after = this.legacySeamTangent ? Math.min(1, parameter + .0001) : parameter + .0001;
    const t = this.point(after).sub(this.point(before)).normalize();
    const n = new Vec3(t.z, 0, -t.x).normalize();
    p.add(n.clone().mulScalar(Number.isFinite(lateral) ? lateral : 0));
    return {p, t, n, u, angle: Math.atan2(t.x, t.z)};
  }
  /** Signed yaw change per metre; positive bends toward the positive lane side. */
  curvature(distance: number, lookAhead = 7): number {
    const span = Number.isFinite(lookAhead) && lookAhead > 0 ? lookAhead : 7;
    const a = this.sample(distance).t, b = this.sample(distance + span).t;
    return Math.atan2(a.z * b.x - a.x * b.z, a.x * b.x + a.z * b.z) / span;
  }
}

src/land-track.ts.content:
import {Vec3} from 'playcanvas';
import {ClosedCircuit, type CircuitPoint} from './closed-circuit';

export type LandSurface = Readonly<{kind: string; grip: number; rollingResistance: number}>;
export type LandSection = Readonly<{name: string; from: number; to: number}>;
export type LandSample = ReturnType<ClosedCircuit['sample']> & {bank: number; normal: Vec3; grade: number};
export interface LandTrack {
  readonly id: string;
  readonly label: string;
  readonly tag: string;
  readonly length: number;
  readonly circuit: ClosedCircuit;
  readonly sections: readonly LandSection[];
  readonly pickups: readonly Readonly<{d: number; lateral: number}>[];
  sample(distance: number, lateral?: number): LandSample;
  halfWidthAt(distance: number): number;
  laneLimitAt(distance: number): number;
  surfaceAt(distance: number): LandSurface;
  clearAt(x: number, z: number, radius?: number): boolean;
}
export type ProfileKey = readonly [fraction: number, value: number];
export const wrapLandDistance = (distance: number, length: number) => ((Number.isFinite(distance) ? distance : 0) % length + length) % length;
const clamp = (n: number, low: number, high: number) => Math.max(low, Math.min(high, n));
/** Periodic smoothstep profile. Keys include matching values at fractions 0/1. */
export function periodicValue(keys: readonly ProfileKey[], fraction: number): number {
  const u = wrapLandDistance(fraction, 1);
  const index = Math.max(1, keys.findIndex((key, i) => i > 0 && key[0] >= u));
  const a = keys[index - 1], b = keys[index];
  const t = clamp((u - a[0]) / (b[0] - a[0]), 0, 1);
  return a[1] + (b[1] - a[1]) * t * t * (3 - 2 * t);
}
export interface LandTrackDefinition {
  id: string; label: string; tag: string; points: readonly CircuitPoint[];
  widths: readonly ProfileKey[];
  /** Sections and pickup distances use lap fractions in the source definition. */
  sections: readonly LandSection[];
  pickups: readonly Readonly<{d: number; lateral: number}>[];
  surfaces?: readonly Readonly<{from: number; to: number; surface: LandSurface}>[];
  bankScale?: number;
}
/** Shared constrained-road geometry, NOT a rigidbody/free-roaming collision engine.
 * The same banked positions feed road vertices, vehicles, pickups and reset support. */
export function createLandTrack(definition: LandTrackDefinition): LandTrack {
  if (definition.widths.length < 2 || definition.widths[0][0] !== 0 || definition.widths.at(-1)![0] !== 1 || definition.widths[0][1] !== definition.widths.at(-1)![1]
    || definition.widths.some(([u, w], i, keys) => !Number.isFinite(u + w) || w < 3 || (i > 0 && u <= keys[i - 1][0]))) throw new Error('Land widths must be finite, ordered, positive and periodic');
  const circuit = new ClosedCircuit(definition.points), length = circuit.length;
  const halfWidthAt = (d: number) => periodicValue(definition.widths, d / length);
  const laneLimitAt = (d: number) => halfWidthAt(d) - .65;
  const asphalt: LandSurface = Object.freeze({kind: 'asphalt', grip: 1, rollingResistance: 1});
  const sample = (distance: number, lateral = 0): LandSample => {
    const frame = circuit.sample(distance);
    const bank = clamp(-circuit.curvature(distance - 5, 10) * (definition.bankScale ?? 5), -.16, .16);
    const baseUp = new Vec3().cross(frame.t, frame.n).normalize();
    const n = frame.n.clone().mulScalar(Math.cos(bank)).add(baseUp.mulScalar(Math.sin(bank))).normalize();
    const normal = new Vec3().cross(frame.t, n).normalize();
    const p = frame.p.add(n.clone().mulScalar(Number.isFinite(lateral) ? lateral : 0));
    return {...frame, p, n, normal, bank, grade: frame.t.y / Math.max(1e-6, Math.hypot(frame.t.x, frame.t.z))};
  };
  // Static roadside placement only; no ambiguity-sensitive nearest-XZ driving.
  const count = Math.ceil(length / 3);
  const clearance = Array.from({length: count}, (_, i) => ({p: sample(i * length / count).p, half: halfWidthAt(i * length / count)}));
  return Object.freeze({
    id: definition.id, label: definition.label, tag: definition.tag, circuit, length, sample, halfWidthAt, laneLimitAt,
    sections: Object.freeze(definition.sections.map(s => Object.freeze({...s, from: s.from * length, to: s.to * length}))),
    pickups: Object.freeze(definition.pickups.map(p => Object.freeze({...p, d: p.d * length}))),
    surfaceAt(distance: number) {
      const u = wrapLandDistance(distance, length) / length;
      return definition.surfaces?.find(s => u >= s.from && u < s.to)?.surface ?? asphalt;
    },
    clearAt(x: number, z: number, radius = 0) {
      return Number.isFinite(x + z + radius) && clearance.every(({p, half}) => Math.hypot(p.x - x, p.z - z) > half + Math.max(0, radius) + 3.5);
    },
  });
}
/** Resolve the deck by canonical track distance, even when X/Z overlaps another deck. */
export function landSupportAt(track: LandTrack, distance: number, lateral = 0) {
  const lane = clamp(Number.isFinite(lateral) ? lateral : 0, -track.laneLimitAt(distance), track.laneLimitAt(distance));
  return {...track.sample(distance, lane), distance: Number.isFinite(distance) ? distance : 0, lateral: lane, surface: track.surfaceAt(distance)};
}
/** Reset keeps the unwrapped lap coordinate and therefore the correct bridge level. */
export function resetLandSupport(track: LandTrack, safeDistance: number, clearance = .6) {
  const support = landSupportAt(track, safeDistance, 0);
  return {...support, p: support.p.clone().add(support.normal.clone().mulScalar(Math.max(0, clearance)))};
}
export type LandLapProgress = Readonly<{distance: number; nextCheckpoint: number; checkpoints: number; passedCheckpoints: number; laps: number}>;
export function createLapProgress(track: LandTrack, distance = 0, checkpointCount = 12): LandLapProgress {
  const d = Number.isFinite(distance) ? distance : 0, count = Number.isFinite(checkpointCount) ? Math.max(4, Math.floor(checkpointCount)) : 12;
  return {distance: d, nextCheckpoint: Math.floor(d / (track.length / count)) + 1, checkpoints: count, passedCheckpoints: 0, laps: 0};
}
/** Explicit physical reset/recovery: preserve earned checkpoint order. A rebase
 * beyond an unearned gate cannot grant it: the racer must return and cross it. */
export function rebaseLapProgress(state: LandLapProgress, safeDistance: number): LandLapProgress {
  return Number.isFinite(safeDistance) ? {...state, distance: safeDistance} : state;
}
/** Call using canonical UNWRAPPED distance after physical integration. Rejected
 * movement does not earn checkpoints. Bounded reversing is physically accepted
 * without credit; nextCheckpoint is monotonic and blocks repeated finish farming.
 * Bounded per-frame progress + lateral support prevent seam/reverse/teleport credit;
 * these are local gameplay checks, not an anti-cheat/server authority boundary. */
export function advanceLapProgress(track: LandTrack, state: LandLapProgress, candidate: number, dt: number, lateral = 0, maxSpeed = 85): {accepted: boolean; state: LandLapProgress; reason?: string} {
  const delta = candidate - state.distance;
  const reject = (reason: string) => ({accepted: false, state, reason});
  if (![candidate, dt, lateral, maxSpeed].every(Number.isFinite) || dt <= 0 || dt > .25 || maxSpeed <= 0) return reject('invalid-step');
  if (Math.abs(delta) > maxSpeed * dt + .03) return reject('teleport');
  if (Math.abs(lateral) > track.laneLimitAt(candidate) + .01) return {accepted: false, state: {...state, distance: candidate}, reason: 'off-road'};
  if (delta <= 0) return {accepted: true, state: {...state, distance: candidate}};
  const spacing = track.length / state.checkpoints;
  let nextCheckpoint = state.nextCheckpoint, laps = state.laps, passedCheckpoints = state.passedCheckpoints;
  while (state.distance < nextCheckpoint * spacing && candidate >= nextCheckpoint * spacing) {
    passedCheckpoints++;
    if (nextCheckpoint > 0 && nextCheckpoint % state.checkpoints === 0 && passedCheckpoints >= state.checkpoints) { laps++; passedCheckpoints = 0; }
    nextCheckpoint++;
  }
  return {accepted: true, state: {...state, distance: candidate, nextCheckpoint, passedCheckpoints, laps}};
}

src/npc-tactics.ts.content:
import { npcLine, type NpcSkill } from './npc-difficulty';
import type { ItemKind } from './item-models';
import { claimPickup, type PickupState } from './item-pickups';
import { PICKUP_LONGITUDINAL_HALF_RANGE, PICKUP_LATERAL_HALF_RANGE } from './pickup-size';

/** Shared race rules: no inventory is generated by the AI. All clocks use race dt. */
export const RULES = Object.freeze({ boost: 3.3, shield: 6, slow: 3, slowFactor: .55, boostFactor: 1.34, pulseRange: 120, lateralSpeed: 4, reaction: .65, cooldown: 1.2 });
export interface Combatant {
  id: string; total: number; lateral: number; speed: number;
  held: ItemKind | null; boost: number; shield: number; slow: number;
}
export interface Brain { bump: number; decisionIn: number; reaction: number; cooldown: number; targetLane: number; pulseFlash: number; pickups: number; uses: number }
export interface RacingPickup extends PickupState { d: number; lateral: number; dynamic?: boolean; edgeId?: string; s?: number }
/** Signed physical route metres; null excludes incompatible branches/decks.
 * Omitted callbacks retain the original single-loop calculations. */
export interface RouteInteractions {
  gap?(actor: Combatant, other: Combatant): number | null;
  pickupGap?(actor: Combatant, box: RacingPickup): number | null;
}
const routeValue = (gap: number | null) => gap !== null && Number.isFinite(gap) ? gap : Infinity;
const racerGap = (actor: Combatant, other: Combatant, length: number, routes?: RouteInteractions, forward = false) => routes?.gap
  ? routeValue(routes.gap(actor, other))
  : (forward ? forwardGap : nearbyGap)(actor.total, other.total, length);
export const newBrain = (phase: number, lane: number): Brain => ({ bump: 0, decisionIn: phase * .047, reaction: 0, cooldown: 0, targetLane: lane, pulseFlash: 0, pickups: 0, uses: 0 });
const clamp = (n: number, low: number, high: number) => Math.max(low, Math.min(high, n));
export const forwardGap = (from: number, to: number, length: number) => { const gap = (to - from) % length; return gap < 0 ? gap + length : gap; };
export const nearbyGap = (from: number, to: number, length: number) => ((to - from + length / 2) % length + length) % length - length / 2;
export const racingSpeed = (r: Combatant, max: number) => clamp(r.speed, 0, max) * (r.boost > 0 ? RULES.boostFactor : 1) * (r.slow > 0 ? RULES.slowFactor : 1);
export function tickEffects(r: Combatant, dt: number) {
  for (const key of ['boost', 'shield', 'slow'] as const) r[key] = Math.max(0, r[key] - Math.max(0, dt));
}
export function tickBrain(b: Brain, dt: number) {
  for (const key of ['bump', 'decisionIn', 'reaction', 'cooldown', 'pulseFlash'] as const) b[key] = Math.max(0, b[key] - Math.max(0, dt));
}
export function pulseTarget(actor: Combatant, racers: readonly Combatant[], length: number, routes?: RouteInteractions) {
  return racers.filter(r => r.id !== actor.id).map(r => ({ r, gap: racerGap(actor, r, length, routes, true) }))
    .filter(t => t.gap > .1 + 1e-8 && t.gap < RULES.pulseRange - 1e-8).sort((a, b) => a.gap - b.gap || a.r.id.localeCompare(b.r.id))[0]?.r;
}
/** A shield stops the nearest incoming pulse; it never skips through to a rear target. */
export function activateItem(actor: Combatant, racers: readonly Combatant[], length: number, routes?: RouteInteractions) {
  const item = actor.held;
  if (!item) return null;
  actor.held = null;
  let target: Combatant | undefined, blocked = false;
  if (item === 'boost') actor.boost = Math.max(actor.boost, RULES.boost);
  else if (item === 'shield') actor.shield = Math.max(actor.shield, RULES.shield);
  else {
    target = pulseTarget(actor, racers, length, routes);
    if (target) { blocked = target.shield > 0; if (!blocked) target.slow = Math.max(target.slow, RULES.slow); }
    else actor.boost = Math.max(actor.boost, 1.9); // Preserve the player's no-target fallback.
  }
  return { item, target, blocked };
}
export function chooseItem(actor: Combatant & Brain, racers: readonly Combatant[], length: number, bend: number, skill?: NpcSkill, routes?: RouteInteractions): ItemKind | null {
  if (!actor.held || actor.reaction > 0 || actor.cooldown > 0) return null;
  const neighbors = racers.filter(r => r.id !== actor.id).map(r => ({ r, gap: racerGap(actor, r, length, routes) }));
  if (actor.held === 'shield') {
    const threatened = neighbors.some(({ r, gap }) => (Math.abs(gap) < 10 && Math.abs(r.lateral - actor.lateral) < 2.3 && (Math.abs(gap) < 4 || (gap > 0 ? actor.speed > r.speed : r.speed > actor.speed))) || (gap < -.1 && gap > -60 && r.held === 'pulse'));
    return actor.shield <= 0 && threatened ? 'shield' : null;
  }
  if (actor.held === 'pulse') { const target = pulseTarget(actor, racers, length, routes); return target && target.shield <= 0 && target.slow < .5 ? 'pulse' : null; }
  const blocked = neighbors.some(({ r, gap }) => gap > 0 && gap < 24 && Math.abs(r.lateral - actor.lateral) < 2.3);
  return actor.boost <= 0 && actor.slow <= 0 && actor.speed > 12 && Math.abs(actor.lateral) < 5.3 && Math.abs(bend) < (skill?.boostBend ?? .3) && !blocked ? 'boost' : null;
}
/** Local, bounded lane planning. Does not inspect pickups beyond 48 m or reverse. */
export function planLane(actor: Combatant, racers: readonly Combatant[], boxes: readonly RacingPickup[], length: number, phase: number, bend: number, skill?: NpcSkill, routes?: RouteInteractions) {
  let lane = skill ? npcLine(actor.total, phase, bend, skill) : Math.sin(actor.total / 90 + phase) * 2.6;
  if (!actor.held && Math.abs(bend) < .5) {
    const candidates = boxes.filter(b => b.cool <= 0 && b.mesh.enabled).map(box => ({ box, gap: routes?.pickupGap ? routeValue(routes.pickupGap(actor, box)) : forwardGap(actor.total, box.d, length) }))
      .filter(({ box, gap }) => gap >= 2 && gap <= (skill?.pickupLookAhead ?? 48) && Math.abs(box.lateral) <= 5.2 && Math.abs(box.lateral - actor.lateral) <= RULES.lateralSpeed * gap / Math.max(12, actor.speed * (actor.boost > 0 ? RULES.boostFactor : 1)) + .65)
      .filter(({ box, gap }) => !racers.some(r => r.id !== actor.id && Math.abs(racerGap(actor, r, length, routes)) < Math.min(gap, 12) && Math.abs(r.lateral - box.lateral) < 1.8))
      .sort((a, b) => (a.gap + Math.abs(a.box.lateral - actor.lateral) * 4) - (b.gap + Math.abs(b.box.lateral - actor.lateral) * 4));
    if (candidates[0]) lane = candidates[0].box.lateral;
  }
  const traffic = racers.filter(r => r.id !== actor.id && Math.abs(r.lateral - lane) < 1.9)
    .map(r => ({ r, gap: racerGap(actor, r, length, routes) })).filter(t => t.gap > -2 && t.gap < 12).sort((a, b) => a.gap - b.gap)[0];
  if (traffic) lane = traffic.r.lateral + (actor.lateral >= traffic.r.lateral ? 2.4 : -2.4);
  return clamp(lane, -5.2, 5.2);
}
export function moveLane(lane: number, target: number, dt: number) {
  return clamp(lane + clamp(target - lane, -RULES.lateralSpeed * Math.max(0, dt), RULES.lateralSpeed * Math.max(0, dt)), -5.2, 5.2);
}
export interface PickupRacer { actor: Combatant; previous: number; previousLane: number; onPickup?: (kind: ItemKind) => void }
/** Authoritative full-frame earliest contact fraction, or null for no contact.
 * The adapter must include route/deck eligibility and all legal movement substeps. */
export type PickupContact = (racer: PickupRacer, box: RacingPickup) => number | null;
/** Swept collision, ordered by time of contact, prevents tunnelling and player-first bias.
 * Exact ties use stable racer IDs rather than frame iteration order. */
export function collectPickups(racers: readonly PickupRacer[], boxes: readonly RacingPickup[], length: number, rng = Math.random, contact?: PickupContact) {
  const claims: { racer: PickupRacer; box: RacingPickup; time: number; index: number }[] = [];
  boxes.forEach((box, index) => {
    if (box.cool > 0 || !box.mesh.enabled) return;
    for (const racer of racers) {
      if (racer.actor.held) continue;
      if (contact) {
        const time = contact(racer, box);
        if (time !== null && Number.isFinite(time) && time >= 0 && time <= 1) claims.push({ racer, box, time, index });
        continue;
      }
      const travel = racer.actor.total - racer.previous;
      // Cover the start's nearest copy and the next crossed lap seam in either direction.
      const base = Math.round((racer.previous - box.d) / length);
      for (let lap = base - 1; lap <= base + 1; lap++) {
        const center = box.d + lap * length;
        let enter = 0, leave = 1;
        for (const [start, delta, low, high] of [[racer.previous, travel, center - PICKUP_LONGITUDINAL_HALF_RANGE, center + PICKUP_LONGITUDINAL_HALF_RANGE], [racer.previousLane, racer.actor.lateral - racer.previousLane, box.lateral - PICKUP_LATERAL_HALF_RANGE, box.lateral + PICKUP_LATERAL_HALF_RANGE]]) {
          if (Math.abs(delta) < 1e-9) { if (start < low || start > high) { enter = 2; break; } }
          else { const a = (low - start) / delta, b = (high - start) / delta; enter = Math.max(enter, Math.min(a, b)); leave = Math.min(leave, Math.max(a, b)); }
        }
        if (enter <= leave && enter <= 1 && leave >= 0) { claims.push({ racer, box, time: enter, index }); break; }
      }
    }
  });
  claims.sort((a, b) => a.time - b.time || a.racer.actor.id.localeCompare(b.racer.actor.id) || a.index - b.index);
  for (const { racer, box } of claims) {
    const reward = claimPickup(box, racer.actor.held !== null, rng);
    if (reward) { racer.actor.held = reward; racer.onPickup?.(reward); }
  }
}

